import { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Activity, Apple, ArrowRight, BarChart3, Bell, BookOpen, Check, ChevronDown, CircleHelp, Clock3,
  Droplets, Flame, HeartPulse, Home, Leaf, Menu, Moon, Plus, Search, Settings2, ShoppingBasket,
  Sparkles, Target, TrendingUp, Utensils, Waves, X, Zap, Camera, ScanLine, LogOut, Sun, UserRound,
  ChevronRight, MoreHorizontal, Play, Footprints, Dumbbell, Coffee, Salad, Soup, GlassWater,
} from 'lucide-react'
import './styles.css'
import './auth.css'


type Section = 'Overview' | 'Nutrition' | 'Activity' | 'Recipes' | 'Goals' | 'Coach' | 'Sleep' | 'Analytics' | 'Planner' | 'Shopping' | 'Profile'
type Meal = { id?: string; type: string; title: string; time: string; kcal: number; protein: number; fat?: number; carbs?: number; fiber?: number; image: string; icon: 'coffee' | 'salad' | 'soup' }
type User = { id: string; name: string; email: string; goal?: string; plan?: string; avatarUrl?: string | null }
type Goal = { id: string; title: string; target: string; progress?: number; progressValue?: number }
const API = import.meta.env.VITE_API_URL || 'http://localhost:4000/api'
const apiFetch = async (path: string, options: RequestInit = {}) => { const token = localStorage.getItem('fitly_token'); const response = await fetch(`${API}${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (response.status === 401 && token) { localStorage.removeItem('fitly_token'); window.location.reload(); } if (!response.ok) throw new Error(data.error || 'Ошибка запроса'); return data }

const navItems: { label: Section; icon: typeof Home; mobile?: boolean }[] = [
  { label: 'Overview', icon: Home, mobile: true }, { label: 'Nutrition', icon: Utensils, mobile: true },
  { label: 'Activity', icon: Activity, mobile: true }, { label: 'Recipes', icon: BookOpen, mobile: true },
  { label: 'Goals', icon: Target }, { label: 'Coach', icon: Sparkles }, { label: 'Sleep', icon: Moon }, { label: 'Analytics', icon: BarChart3 }, { label: 'Planner', icon: Coffee }, { label: 'Shopping', icon: ShoppingBasket }, { label: 'Profile', icon: UserRound, mobile: true },
]
const sectionLabels: Record<Section, string> = { Overview: 'Обзор', Nutrition: 'Питание', Activity: 'Активность', Recipes: 'Рецепты', Goals: 'Цели', Coach: 'FITLY AI', Sleep: 'Сон', Analytics: 'Аналитика', Planner: 'Планировщик', Shopping: 'Покупки', Profile: 'Профиль' }

type Recipe = { id: string; name: string; minutes: number; kcal: number; tag: string; image?: string }

function App() {
  const [session, setSession] = useState(() => localStorage.getItem('fitly_token'))
  if (!session) return <AuthScreen onAuth={(token) => { localStorage.setItem('fitly_token', token); setSession(token) }} />
  return <AuthenticatedApp onLogout={() => { localStorage.removeItem('fitly_token'); setSession(null) }} />
}

function AuthenticatedApp({ onLogout }: { onLogout: () => void }) {
  const [section, setSection] = useState<Section>('Overview')
  const [user, setUser] = useState<User | null>(null)
  const [mealItems, setMealItems] = useState<Meal[]>([])
  const [recipes, setRecipes] = useState<Recipe[]>([])
  const [goals, setGoals] = useState<Goal[]>([])
  const [dark, setDark] = useState(false)
  const [water, setWater] = useState(0)
  const [steps, setSteps] = useState(0)
  const [showAdd, setShowAdd] = useState(false)
  const [showScanner, setShowScanner] = useState(false)
  const [toast, setToast] = useState('')
  const [search, setSearch] = useState('')
  const [checkedHabits, setCheckedHabits] = useState<boolean[]>([])
  const [habitLabels, setHabitLabels] = useState<string[]>([])
  const reloadData = async () => { try { const [profile, loggedMeals, loggedWater, recipeData, goalData, habitData, settings, activityData] = await Promise.all([apiFetch('/me'), apiFetch('/meals'), apiFetch('/water'), apiFetch('/recipes'), apiFetch('/goals'), apiFetch('/habits'), apiFetch('/settings'), apiFetch('/activity')]); setUser(profile.user); setRecipes(recipeData.items || []); setGoals(goalData.items || []); setMealItems((loggedMeals.items || []).map((m: { id: string; title: string; type: string; kcal: number; protein: number; date: string }) => ({ ...m, time: new Date(m.date).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' }), image: '', icon: 'salad' as const }))); setWater((loggedWater.items || []).filter((x: { date: string }) => x.date.slice(0, 10) === new Date().toISOString().slice(0, 10)).reduce((sum: number, x: { amount: number }) => sum + x.amount, 0) / 250); setSteps((activityData.items || []).filter((x: { date: string }) => x.date.slice(0, 10) === new Date().toISOString().slice(0, 10)).reduce((sum: number, x: { steps: number }) => sum + x.steps, 0)); setCheckedHabits((habitData.items || []).map((h: { checkedToday?: boolean }) => !!h.checkedToday)); setHabitLabels((habitData.items || []).map((h: { title: string }) => h.title)); if (settings.settings?.theme) setDark(settings.settings.theme === 'dark') } catch { onLogout() } }
  // Load the authenticated user's data once when the app shell mounts.
  useEffect(() => { const refresh = () => { reloadData() }; reloadData(); window.addEventListener('fitly:data-changed', refresh); return () => window.removeEventListener('fitly:data-changed', refresh) }, [])
  useEffect(() => {
    const openPicker = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null
      if (target?.closest('.edit-avatar')) document.getElementById('avatar-upload')?.click()
    }
    document.addEventListener('click', openPicker)
    return () => document.removeEventListener('click', openPicker)
  }, [])
  const uploadAvatar = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    event.target.value = ''
    if (!file) return
    if (!file.type.startsWith('image/')) return notify('Выберите файл изображения')
    if (file.size > 1_500_000) return notify('Аватар должен быть меньше 1.5 МБ')
    const reader = new FileReader()
    reader.onload = async () => {
      try {
        const data = await apiFetch('/profile', { method: 'PATCH', body: JSON.stringify({ avatarUrl: String(reader.result || '') }) })
        setUser(data.user)
        notify('Аватар сохранён')
      } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить аватар') }
    }
    reader.readAsDataURL(file)
  }
  useEffect(() => {
    const frame = window.requestAnimationFrame(() => {
      const element = document.querySelector('.profile-avatar')
      if (!element || !user) return
      element.replaceChildren()
      if (user.avatarUrl) {
        const image = document.createElement('img')
        image.src = user.avatarUrl
        image.alt = 'Аватар профиля'
        image.onerror = () => { image.remove(); element.textContent = user.name.slice(0, 2).toUpperCase() || 'FT' }
        element.appendChild(image)
      } else element.textContent = user.name.slice(0, 2).toUpperCase() || 'FT'
    })
    return () => window.cancelAnimationFrame(frame)
  }, [user, section])

  const notify = (message: string) => { const visible = message.includes('storage provider') ? 'Выберите изображение для аватара' : message; setToast(visible); window.setTimeout(() => setToast(''), 2800) }
  const toggleHabit = async (i: number) => { const habits = await apiFetch('/habits').catch(() => ({ items: [] })); const habit = habits.items?.[i]; if (!habit) return notify('Сначала создайте привычку в разделе привычек'); try { const completed = !checkedHabits[i]; await apiFetch('/habits/check', { method: 'POST', body: JSON.stringify({ id: habit.id, completed }) }); setCheckedHabits(old => old.map((v, idx) => idx === i ? completed : v)) } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось обновить привычку') } }
  const createHabit = async () => { const title = window.prompt('Название привычки'); if (!title?.trim()) return; const target = window.prompt('Цель или частота (необязательно)', '') || undefined; try { await apiFetch('/habits', { method: 'POST', body: JSON.stringify({ title: title.trim(), target }) }); await reloadData(); notify('Привычка создана') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось создать привычку') } }
  const currentDate = new Intl.DateTimeFormat('ru-RU', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date())
  const waterPercent = Math.round((water / 8) * 100)
  const filteredRecipes = useMemo(() => recipes.filter(r => r.name.toLowerCase().includes(search.toLowerCase())), [recipes, search])

  return <div className={dark ? 'app dark' : 'app'}>
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Leaf size={18} strokeWidth={2.6} /></div><span>FITLY</span></div>
      <div className="sidebar-label">Рабочий стол</div>
      <nav>{navItems.map(({ label, icon: Icon }) => <button key={label} className={section === label ? 'nav-item active' : 'nav-item'} onClick={() => setSection(label)}><Icon size={18} /><span>{sectionLabels[label]}</span>{label === 'Coach' && <span className="new-badge">AI</span>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="streak-card"><div className="streak-icon"><Flame size={17} /></div><div><b>0 дней</b><span>текущий streak</span></div><ChevronRight size={16} /></div><button className="settings-link" onClick={() => setSection('Profile')}><Settings2 size={17} /> Настройки</button></div>
      <div className="sidebar-user"><div className="avatar">{user?.avatarUrl ? <img src={user.avatarUrl} alt="" onError={e => { const parent = e.currentTarget.parentElement; e.currentTarget.remove(); if (parent) parent.textContent = user?.name?.slice(0, 2).toUpperCase() || 'FT' }} /> : user?.name?.slice(0, 2).toUpperCase() || 'FT'}</div><div><b>{user?.name || 'Загрузка…'}</b><span>{user?.plan || 'Free'} план</span></div><MoreHorizontal size={18} /></div>
    </aside>

    <main className="main">
      <header className="topbar"><div className="mobile-brand"><div className="brand-mark"><Leaf size={16} /></div><span>FITLY</span></div><div className="breadcrumbs"><span>Рабочий стол</span><ChevronRight size={14} /><b>{section === 'Overview' ? 'Обзор' : section}</b></div><div className="top-actions"><button className="icon-button" aria-label="Помощь" onClick={() => notify('Откройте FITLY AI для вопросов после настройки провайдера')}><CircleHelp size={19} /></button><button className="icon-button notification" aria-label="Уведомления" onClick={() => notify('Уведомления не настроены')}><Bell size={19} /></button><button className="theme-toggle" onClick={() => setDark(!dark)} aria-label="Переключить тему">{dark ? <Sun size={17} /> : <Moon size={17} />}</button><div className="top-profile"><div className="avatar small">{user?.avatarUrl ? <img src={user.avatarUrl} alt="" onError={e => { const parent = e.currentTarget.parentElement; e.currentTarget.remove(); if (parent) parent.textContent = user?.name?.slice(0, 2).toUpperCase() || 'FT' }} /> : user?.name?.slice(0, 2).toUpperCase() || 'FT'}</div><ChevronDown size={15} /></div></div></header>
      <AnimatePresence mode="wait"><motion.div key={section} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -6 }} transition={{ duration: .22 }} className="page">
        {section === 'Overview' && <Overview name={user?.name || ''} mealItems={mealItems} steps={steps} currentDate={currentDate} water={water} waterPercent={waterPercent} setWater={async (n) => { if (n > water) await apiFetch('/water', { method: 'POST', body: JSON.stringify({ amount: 250 }) }); await reloadData() }} setShowAdd={setShowAdd} setShowScanner={setShowScanner} notify={notify} checkedHabits={checkedHabits} habitLabels={habitLabels} toggleHabit={toggleHabit} createHabit={createHabit} />}
        {section === 'Nutrition' && <Nutrition mealItems={mealItems} notify={notify} setShowAdd={setShowAdd} setShowScanner={setShowScanner} />}
        {section === 'Activity' && <ActivityPage notify={notify} onAdded={reloadData} />}
        {section === 'Recipes' && <Recipes search={search} setSearch={setSearch} recipes={filteredRecipes} notify={notify} />}
        {section === 'Goals' && <Goals goals={goals} notify={notify} onCreated={reloadData} />}
        {section === 'Coach' && <Coach notify={notify} />}
        {section === 'Sleep' && <SleepPage notify={notify} />}
        {section === 'Analytics' && <AnalyticsPage notify={notify} />}
        {section === 'Planner' && <PlannerPage recipes={recipes} notify={notify} />}
        {section === 'Shopping' && <ShoppingPage notify={notify} />}
        {section === 'Profile' && <Profile name={user?.name || ''} dark={dark} setDark={setDark} notify={notify} onLogout={onLogout} />}
      </motion.div></AnimatePresence>
    </main>
    <div className="mobile-nav">{navItems.filter(n => n.mobile).map(({ label, icon: Icon }) => <button key={label} className={section === label ? 'active' : ''} onClick={() => setSection(label)}><Icon size={19} /><span>{label === 'Overview' ? 'Главная' : label === 'Nutrition' ? 'Питание' : label === 'Activity' ? 'Движение' : label === 'Recipes' ? 'Рецепты' : 'Профиль'}</span></button>)}</div>
    <input id="avatar-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden onChange={uploadAvatar} />
    <AnimatePresence>{showAdd && <AddFoodModal close={() => setShowAdd(false)} notify={notify} onAdded={reloadData} />}</AnimatePresence>
    <AnimatePresence>{showScanner && <ScannerModal close={() => setShowScanner(false)} notify={notify} />}</AnimatePresence>
    <AnimatePresence>{toast && <motion.div className="toast" initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 15 }}><Check size={17} />{toast}</motion.div>}</AnimatePresence>
  </div>
}

function Overview({ name, mealItems, steps, currentDate, water, waterPercent, setWater, setShowAdd, setShowScanner, notify, checkedHabits, habitLabels, toggleHabit, createHabit }: { name: string; mealItems: Meal[]; steps: number; currentDate: string; water: number; waterPercent: number; setWater: (n: number) => void; setShowAdd: (v: boolean) => void; setShowScanner: (v: boolean) => void; notify: (s: string) => void; checkedHabits: boolean[]; habitLabels: string[]; toggleHabit: (i: number) => void; createHabit: () => Promise<void> }) {
  const loggedMeals = mealItems.length ? mealItems : []
  const kcal = loggedMeals.reduce((sum, item) => sum + item.kcal, 0)
  const protein = loggedMeals.reduce((sum, item) => sum + item.protein, 0)
  return <><div className="page-heading"><div><p className="eyebrow">{currentDate.charAt(0).toUpperCase() + currentDate.slice(1)}</p><h1>Доброе утро, {name || 'вам'} <span>✦</span></h1><p className="subheading">Пусть сегодня будет в вашем ритме.</p></div><div className="heading-actions"><button className="button secondary" onClick={() => setShowScanner(true)}><ScanLine size={17} /> Сканировать</button><button className="button primary" onClick={() => setShowAdd(true)}><Plus size={17} /> Добавить</button></div></div>
    <div className="hero-grid"><section className="card daily-score"><div className="card-top"><div><span className="section-kicker">Ваш день</span><h2>{loggedMeals.length ? 'Данные записаны' : 'Начните с первой записи'}</h2></div><button className="dots" onClick={() => notify('Сводка строится из ваших записей')}><MoreHorizontal size={19} /></button></div><div className="score-body"><div className="ring" style={{ '--progress': '0%' } as React.CSSProperties}><div><strong>0</strong><span>/ 100</span></div></div><div className="score-copy"><b>{loggedMeals.length ? 'Есть первые данные' : 'Пока нет данных'}</b><p>{loggedMeals.length ? 'Добавляйте записи регулярно, чтобы увидеть персональную аналитику.' : 'Добавьте питание, воду или активность — FITLY рассчитает ваш день.'}</p><div className="progress-bar"><i style={{ width: '0%' }} /></div><span className="muted">Оценка появится после подключения аналитики</span></div></div><div className="day-timeline"><TimelineIcon icon={<Coffee size={15} />} label="Завтрак" /><TimelineIcon icon={<Salad size={15} />} label="Обед" /><TimelineIcon icon={<GlassWater size={15} />} label="Вода" /><TimelineIcon icon={<Dumbbell size={15} />} label="Движение" /><TimelineIcon icon={<Moon size={15} />} label="Сон" /></div></section><section className="card ai-card"><div className="ai-orb"><Sparkles size={22} /></div><span className="section-kicker">FITLY AI</span><h2>Local AI активен</h2><p>Бесплатный коуч анализирует реальные записи дневника без внешнего ключа.</p><button className="text-button" onClick={() => notify('Откройте FITLY AI и задайте вопрос')}>Открыть коуч <ArrowRight size={16} /></button><div className="ai-pattern"><span /><span /><span /></div></section></div>
    <div className="metric-grid"><MetricCard icon={<Flame size={19} />} label="Калории" value={`${kcal}`} target="из 2 100 ккал" percent={Math.min(100, kcal / 21)} tone="orange" /><MetricCard icon={<HeartPulse size={19} />} label="Белок" value={`${protein} г`} target="из 120 г" percent={Math.min(100, protein / 1.2)} tone="green" /><MetricCard icon={<Waves size={19} />} label="Вода" value={`${water * 250} мл`} target="из 2 000 мл" percent={waterPercent} tone="blue" action={<button className="mini-plus" onClick={() => setWater(water + 1)}><Plus size={15} /></button>} /><MetricCard icon={<Footprints size={19} />} label="Шаги" value={String(steps)} target="Источник: manual" percent={0} tone="purple" /></div>
    <div className="content-grid"><section className="card meals-card"><div className="card-top"><div><span className="section-kicker">Питание сегодня</span><h2>Ваши приёмы пищи <span className="count-pill">{loggedMeals.length}</span></h2></div><button className="text-button muted" onClick={() => notify('История питания открыта')}>Вся история <ArrowRight size={15} /></button></div><div className="meal-list">{loggedMeals.length ? loggedMeals.map((meal, i) => <MealRow key={meal.id || meal.title + i} meal={meal} index={i} notify={notify} />) : <div className="empty-state"><Utensils size={20} /><b>Дневник пока пуст</b><span>Добавьте первый приём пищи, чтобы начать отслеживание.</span></div>}<button className="add-meal" onClick={() => setShowAdd(true)}><Plus size={17} /> Добавить приём пищи</button></div></section><section className="card habit-card"><div className="card-top"><div><span className="section-kicker">Привычки</span><h2>Сегодня <span className="count-pill green-pill">{checkedHabits.filter(Boolean).length} / {habitLabels.length}</span></h2></div><button className="dots" onClick={createHabit}><Plus size={19} /></button></div><div className="habit-list">{habitLabels.length ? habitLabels.map((habit, i) => <button key={habit} className="habit-row" onClick={() => toggleHabit(i)}><span className={checkedHabits[i] ? 'check checked' : 'check'}>{checkedHabits[i] && <Check size={13} />}</span><span>{habit}</span><span className="habit-streak">—</span></button>) : <div className="empty-state"><Target size={18} /><span>Привычек пока нет.</span></div>}</div><button className="button outline full" onClick={createHabit}><Target size={16} /> Создать привычку</button></section></div>
    <section className="card weekly-card"><div className="empty-state"><BarChart3 size={22} /><b>Аналитика появится после первых записей</b><span>Добавьте питание, воду или активность, чтобы увидеть реальные данные.</span></div></section>
  </>
}

function TimelineIcon({ icon, label, done, active }: { icon: React.ReactNode; label: string; done?: boolean; active?: boolean }) { return <div className={done ? 'timeline-item done' : active ? 'timeline-item active' : 'timeline-item'}><div className="timeline-icon">{done ? <Check size={14} /> : icon}</div><span>{label}</span></div> }
function MetricCard({ icon, label, value, target, percent, tone, action }: { icon: React.ReactNode; label: string; value: string; target: string; percent: number; tone: string; action?: React.ReactNode }) { return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><div className="metric-label">{label}{action}</div><b className="metric-value">{value}</b><span className="metric-target">{target}</span><div className="tiny-progress"><i className={tone} style={{ width: `${percent}%` }} /></div></div> }
function MealRow({ meal, index, notify }: { meal: Meal; index: number; notify: (s: string) => void }) { const Icon = meal.icon === 'coffee' ? Coffee : meal.icon === 'salad' ? Salad : Soup; const remove = async () => { if (!meal.id || !window.confirm(`Удалить «${meal.title}»?`)) return; try { await apiFetch(`/meals/${meal.id}`, { method: 'DELETE' }); window.dispatchEvent(new Event('fitly:data-changed')); notify('Приём пищи удалён') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось удалить запись') } }; return <div className="meal-row"><div className="meal-image"><img src={meal.image} alt="" /><div className="meal-icon"><Icon size={15} /></div></div><div className="meal-info"><span>{meal.type} · {meal.time}</span><b>{meal.title}</b><small><Flame size={12} /> {meal.kcal} ккал <i /> <HeartPulse size={12} /> {meal.protein} г белка</small></div><button className="row-more" aria-label="Удалить приём пищи" onClick={remove}><MoreHorizontal size={18} /></button></div> }

function Nutrition({ mealItems, notify, setShowAdd, setShowScanner }: { mealItems: Meal[]; notify: (s: string) => void; setShowAdd: (v: boolean) => void; setShowScanner: (v: boolean) => void }) { const kcal = mealItems.reduce((sum, item) => sum + item.kcal, 0); const protein = mealItems.reduce((sum, item) => sum + item.protein, 0); const fat = mealItems.reduce((sum, item) => sum + (item.fat || 0), 0); const carbs = mealItems.reduce((sum, item) => sum + (item.carbs || 0), 0); return <><PageTitle eyebrow="Питание" title="Питайтесь с пониманием" sub="Все данные о рационе — в одном спокойном пространстве." action={<><button className="button secondary" onClick={() => setShowScanner(true)}><ScanLine size={17} /> Сканировать</button><button className="button primary" onClick={() => setShowAdd(true)}><Plus size={17} /> Добавить еду</button></>} /><div className="nutrition-tabs"><button className="active">Сегодня</button><button onClick={() => notify('История строится из сохранённых записей')}>История</button><button onClick={() => notify('Откройте раздел аналитики после добавления записей')}>Аналитика</button><button onClick={() => notify('Избранные продукты доступны через базу продуктов')}>Избранное</button></div><div className="nutrition-layout"><section className="card nutrition-summary"><div className="summary-ring ring-sm" style={{ '--progress': `${Math.min(100, kcal / 21)}%` } as React.CSSProperties}><div><b>{kcal}</b><span>ккал</span></div></div><div><span className="section-kicker">Баланс дня</span><h2>Ещё {Math.max(0, 2100 - kcal)} ккал</h2><p className="muted">Данные рассчитаны по вашим добавленным блюдам.</p></div><button className="dots"><MoreHorizontal size={19} /></button><div className="macro-bars"><Macro label="Белки" value={`${protein.toFixed(1)} г`} percent={Math.min(100, protein / 1.2)} color="green" /><Macro label="Жиры" value={`${fat.toFixed(1)} г`} percent={Math.min(100, fat / 0.7)} color="orange" /><Macro label="Углеводы" value={`${carbs.toFixed(1)} г`} percent={Math.min(100, carbs / 2.5)} color="blue" /></div></section><section className="card quick-add"><span className="section-kicker">Быстрый доступ</span><h2>Добавить продукт</h2><div className="quick-actions"><button onClick={() => setShowScanner(true)}><div className="qa-icon purple"><Camera size={19} /></div><span>Фото блюда</span><small>AI Scanner</small></button><button onClick={() => setShowAdd(true)}><div className="qa-icon green"><Search size={19} /></div><span>Найти продукт</span><small>База FITLY</small></button><button onClick={() => notify('Штрихкод: введите код через поиск продуктов') }><div className="qa-icon orange"><ScanLine size={19} /></div><span>Штрихкод</span><small>Ручной ввод</small></button></div></section></div><section className="card food-log"><div className="card-top"><div><span className="section-kicker">Дневник</span><h2>Сегодня</h2></div><button className="select-button">Сортировка <ChevronDown size={15} /></button></div>{mealItems.length ? mealItems.map((m, i) => <MealRow key={m.id || m.title + i} meal={m} index={i} notify={notify} />) : <div className="empty-state"><Utensils size={20} /><b>Нет записей за сегодня</b><span>Добавьте блюдо, чтобы увидеть статистику.</span></div>}<button className="add-meal" onClick={() => setShowAdd(true)}><Plus size={17} /> Добавить приём пищи</button></section></> }
function Macro({ label, value, percent, color }: { label: string; value: string; percent: number; color: string }) { return <div className="macro"><div><span>{label}</span><b>{value}</b></div><div className="macro-bar"><i className={color} style={{ width: `${percent}%` }} /></div></div> }

function ActivityPage({ notify, onAdded }: { notify: (s: string) => void; onAdded: () => Promise<void> }) { const [items, setItems] = useState<Array<{ steps: number; activeMinutes: number; source: string }>>([]); useEffect(() => { apiFetch('/activity').then(data => setItems(data.items || [])).catch(() => notify('Не удалось загрузить активность')) }, [notify]); const steps = items.reduce((sum, x) => sum + x.steps, 0); const minutes = items.reduce((sum, x) => sum + x.activeMinutes, 0); const add = async () => { const stepInput = window.prompt('Шаги', '0'); if (stepInput === null) return; const minuteInput = window.prompt('Активные минуты', '0'); if (minuteInput === null) return; try { await apiFetch('/activity', { method: 'POST', body: JSON.stringify({ steps: Number(stepInput), activeMinutes: Number(minuteInput), source: 'manual' }) }); setItems((await apiFetch('/activity')).items || []); await onAdded(); notify('Активность сохранена') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить активность') } }; const integrations = async () => { try { const data = await apiFetch('/integrations'); const count = (data.providers || []).filter((x: { status: string }) => x.status === 'connected').length; notify(count ? `${count} источник(а) подключено` : 'Подключённых устройств нет. Ручной ввод доступен.') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось загрузить интеграции') } }; return <><PageTitle eyebrow="Активность" title="Двигайтесь в своём ритме" sub="Данные появятся после ручного ввода или подключения устройства." action={<button className="button primary" onClick={add}><Plus size={17} /> Добавить активность</button>} /><div className="metric-grid activity-metrics"><MetricCard icon={<Footprints size={19} />} label="Шаги" value={String(steps)} target="Источник: manual" percent={0} tone="green" /><MetricCard icon={<Clock3 size={19} />} label="Активные минуты" value={String(minutes)} target="Источник: manual" percent={0} tone="blue" /><MetricCard icon={<Flame size={19} />} label="Активные ккал" value="—" target="Источник не подключён" percent={0} tone="orange" /><MetricCard icon={<HeartPulse size={19} />} label="Пульс" value="—" target="Нет источника" percent={0} tone="purple" /></div><div className="content-grid"><section className="card weekly-card activity-chart">{items.length ? <div className="meal-list">{items.map((x, i) => <div className="meal-row" key={`${x.source}-${i}`}><span>{x.steps} шагов</span><small>{x.activeMinutes} мин · {x.source}</small></div>)}</div> : <div className="empty-state"><Activity size={22} /><b>Нет данных активности</b><span>Добавьте запись вручную или подключите устройство.</span></div>}</section><section className="card connected-card"><div className="section-kicker">Интеграции</div><h2>Источники активности</h2><p className="muted">Статусы загружаются из аккаунта, ручной ввод доступен всегда.</p><button className="button outline full" onClick={integrations}>Проверить интеграции <ArrowRight size={15} /></button></section></div></> }

function Recipes({ search, setSearch, recipes, notify }: { search: string; setSearch: (s: string) => void; recipes: Recipe[]; notify: (s: string) => void }) { const [favorites, setFavorites] = useState<string[]>([]); useEffect(() => { apiFetch('/favorites').then(data => setFavorites((data.items || []).map((x: { recipeId: string }) => x.recipeId))).catch(() => undefined) }, []); const toggleFavorite = async (id: string) => { const active = favorites.includes(id); try { await apiFetch(`/recipes/${id}/favorite`, { method: active ? 'DELETE' : 'POST' }); setFavorites(old => active ? old.filter(x => x !== id) : [...old, id]); notify(active ? 'Рецепт удалён из избранного' : 'Рецепт добавлен в избранное') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить избранное') } }; return <><PageTitle eyebrow="Рецепты" title="Вдохновение на каждый день" sub="Рецепты из базы FITLY." action={<button className="button secondary" onClick={() => notify('Local AI готовит рецепты по вашим продуктам') }><Sparkles size={17} /> FITLY AI</button>} /><div className="recipe-search"><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Поиск по рецептам" /><button onClick={() => notify(`${recipes.length} рецептов найдено`)}><ArrowRight size={17} /></button></div><div className="chip-row"><button className="active">Все</button></div><div className="recipes-grid">{recipes.length ? recipes.map(recipe => <motion.article className="recipe-card" key={recipe.id} whileHover={{ y: -4 }}><div className="recipe-image">{recipe.image ? <img src={recipe.image} alt="" /> : <div className="empty-image"><Utensils size={24} /></div>}<span>{recipe.tag}</span><button aria-label={favorites.includes(recipe.id) ? 'Убрать из избранного' : 'Добавить в избранное'} onClick={() => toggleFavorite(recipe.id)}>{favorites.includes(recipe.id) ? '♥' : '♡'}</button></div><div className="recipe-copy"><h3>{recipe.name}</h3><p>{recipe.minutes} мин · {recipe.kcal} ккал</p><button className="text-button" onClick={() => notify(`Рецепт «${recipe.name}» загружен из API`)}>Смотреть рецепт <ArrowRight size={15} /></button></div></motion.article>) : <div className="empty-state"><BookOpen size={22} /><b>Рецептов пока нет</b><span>Добавьте рецепты через API seed или подключите каталог.</span></div>}</div></> }

function Goals({ goals, notify, onCreated }: { goals: Goal[]; notify: (s: string) => void; onCreated: () => Promise<void> }) { const createGoal = async () => { const title = window.prompt('Название цели'); if (!title) return; try { await apiFetch('/goals', { method: 'POST', body: JSON.stringify({ title, target: 'Пользовательская цель' }) }); await onCreated(); notify('Цель сохранена') } catch (e) { notify(e instanceof Error ? e.message : 'Ошибка сохранения') } }; const removeGoal = async (id: string) => { if (!window.confirm('Удалить эту цель?')) return; try { await apiFetch(`/goals/${id}`, { method: 'DELETE' }); await onCreated(); notify('Цель удалена') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось удалить цель') } }; return <><PageTitle eyebrow="Цели" title="Цели, которые поддерживают" sub="Цели из вашего аккаунта." action={<button className="button primary" onClick={createGoal}><Plus size={17} /> Новая цель</button>} />{goals.length ? <div className="goals-grid">{goals.map(goal => { const progress = goal.progressValue ?? goal.progress ?? 0; return <div className="card goal-card" key={goal.id}><div className="goal-icon green"><Target size={19} /></div><div className="goal-head"><div><h3>{goal.title}</h3><p>{goal.target}</p></div><button className="dots" aria-label="Удалить цель" onClick={() => removeGoal(goal.id)}><MoreHorizontal size={18} /></button></div><div className="goal-progress"><i className="green" style={{ width: `${Math.min(100, progress)}%` }} /></div><div className="goal-foot"><b>{progress}%</b><span>из данных аккаунта</span></div></div> })}</div> : <section className="card weekly-card"><div className="empty-state"><Target size={22} /><b>Целей пока нет</b><span>Создайте первую цель — её прогресс будет рассчитан из ваших записей.</span></div></section>}</> }

function SleepPage({ notify }: { notify: (s: string) => void }) { const [items, setItems] = useState<Array<{ id: string; durationMinutes: number; source: string; date: string }>>([]); const load = () => apiFetch('/sleep').then(data => setItems(data.items || [])).catch(() => notify('Не удалось загрузить сон')); useEffect(() => { void load() }, []); const add = async () => { const hours = window.prompt('Сколько часов сна?', '8'); if (hours === null) return; try { await apiFetch('/sleep', { method: 'POST', body: JSON.stringify({ durationMinutes: Math.round(Number(hours) * 60), source: 'manual' }) }); await load(); notify('Сон сохранён') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить сон') } }; const average = items.length ? items.reduce((sum, x) => sum + x.durationMinutes, 0) / items.length : 0; return <><PageTitle eyebrow="Сон" title="Восстановление в вашем ритме" sub="Ручные записи и данные подключённых источников." action={<button className="button primary" onClick={add}><Plus size={17} /> Добавить сон</button>} /><section className="card weekly-card"><div className="metric-grid"><MetricCard icon={<Moon size={19} />} label="Средняя длительность" value={`${(average / 60).toFixed(1)} ч`} target="По сохранённым записям" percent={0} tone="purple" /></div>{items.length ? <div className="meal-list">{items.map(item => <div className="meal-row" key={item.id}><div className="meal-info"><b>{(item.durationMinutes / 60).toFixed(1)} ч сна</b><small>{new Date(item.date).toLocaleDateString('ru-RU')} · {item.source}</small></div><button className="row-more" onClick={async () => { await apiFetch(`/sleep/${item.id}`, { method: 'DELETE' }); await load(); notify('Запись удалена') }}><X size={16} /></button></div>)}</div> : <div className="empty-state"><Moon size={22} /><b>Записей сна пока нет</b><span>Добавьте первую запись.</span></div>}</section></> }

function AnalyticsPage({ notify }: { notify: (s: string) => void }) { const [days, setDays] = useState<Array<{ date: string; calories: number; water: number; steps: number; sleepMinutes: number; habits: number }>>([]); const [period, setPeriod] = useState(7); useEffect(() => { apiFetch(`/analytics?days=${period}`).then(data => setDays(data.days || [])).catch(() => notify('Не удалось загрузить аналитику')) }, [period]); const total = days.reduce((a, x) => ({ calories: a.calories + x.calories, water: a.water + x.water, steps: a.steps + x.steps, sleep: a.sleep + x.sleepMinutes }), { calories: 0, water: 0, steps: 0, sleep: 0 }); return <><PageTitle eyebrow="Аналитика" title="Ваши реальные тренды" sub="Расчёты только из данных аккаунта." action={<select className="select-button" value={period} onChange={e => setPeriod(Number(e.target.value))}><option value={7}>7 дней</option><option value={30}>30 дней</option><option value={90}>90 дней</option></select>} /><div className="metric-grid"><MetricCard icon={<Flame size={19} />} label="Калории" value={String(Math.round(total.calories))} target="за период" percent={0} tone="orange" /><MetricCard icon={<Waves size={19} />} label="Вода" value={`${Math.round(total.water)} мл`} target="за период" percent={0} tone="blue" /><MetricCard icon={<Footprints size={19} />} label="Шаги" value={String(total.steps)} target="за период" percent={0} tone="purple" /><MetricCard icon={<Moon size={19} />} label="Сон" value={`${(total.sleep / 60).toFixed(1)} ч`} target="за период" percent={0} tone="green" /></div><section className="card weekly-card">{days.some(day => day.calories || day.water || day.steps || day.sleepMinutes) ? <div className="meal-list">{days.map(day => <div className="meal-row" key={day.date}><div className="meal-info"><b>{day.date}</b><small>{Math.round(day.calories)} ккал · {Math.round(day.water)} мл · {day.steps} шагов · {(day.sleepMinutes / 60).toFixed(1)} ч сна</small></div></div>)}</div> : <div className="empty-state"><BarChart3 size={22} /><b>Недостаточно данных</b><span>Добавьте питание, воду, активность или сон.</span></div>}</section></> }

function PlannerPage({ recipes, notify }: { recipes: Recipe[]; notify: (s: string) => void }) { const [items, setItems] = useState<Array<{ id: string; type: string; recipe?: { name: string } }>>([]); const load = () => apiFetch('/meal-plans').then(data => setItems((data.items || []).flatMap((x: { items: Array<{ id: string; type: string; recipe?: { name: string } }> }) => x.items))).catch(() => notify('Не удалось загрузить план')); useEffect(() => { void load() }, []); const add = async () => { const recipe = recipes[0]; if (!recipe) return notify('Сначала добавьте рецепт в базу'); try { await apiFetch('/meal-plans', { method: 'POST', body: JSON.stringify({ recipeId: recipe.id, type: 'dinner', date: new Date().toISOString() }) }); await load(); notify('Рецепт добавлен в план') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось добавить в план') } }; return <><PageTitle eyebrow="Планировщик" title="План питания" sub="Сохраняйте блюда по дням и типам приёма пищи." action={<button className="button primary" onClick={add}><Plus size={17} /> Добавить рецепт</button>} /><section className="card weekly-card">{items.length ? <div className="meal-list">{items.map(item => <div className="meal-row" key={item.id}><div className="meal-info"><span>{item.type}</span><b>{item.recipe?.name || 'Продукт'}</b></div><button className="row-more" onClick={async () => { await apiFetch(`/meal-plans/items/${item.id}`, { method: 'DELETE' }); await load(); notify('Блюдо удалено') }}><X size={16} /></button></div>)}</div> : <div className="empty-state"><Coffee size={22} /><b>План пуст</b><span>Добавьте рецепт из вашей базы.</span></div>}</section></> }

function ShoppingPage({ notify }: { notify: (s: string) => void }) { const [list, setList] = useState<{ id: string; name: string; items: Array<{ id: string; name: string; quantity: number; purchased: boolean }> } | null>(null); const load = () => apiFetch('/shopping-lists').then(async data => { const current = data.items?.[0]; if (current) setList(current); else setList((await apiFetch('/shopping-lists', { method: 'POST', body: JSON.stringify({ name: 'Мой список' }) })).item) }).catch(() => notify('Не удалось загрузить покупки')); useEffect(() => { void load() }, []); const add = async () => { if (!list) return; const name = window.prompt('Что купить?'); if (!name?.trim()) return; await apiFetch(`/shopping-lists/${list.id}/items`, { method: 'POST', body: JSON.stringify({ name: name.trim(), quantity: 1 }) }); await load(); notify('Товар добавлен') }; return <><PageTitle eyebrow="Покупки" title="Список покупок" sub="Товары сохраняются в вашем аккаунте." action={<button className="button primary" onClick={add}><Plus size={17} /> Добавить товар</button>} /><section className="card weekly-card">{list?.items?.length ? <div className="meal-list">{list.items.map(item => <div className="meal-row" key={item.id}><button className={item.purchased ? 'check checked' : 'check'} onClick={async () => { await apiFetch(`/shopping-lists/${list.id}/items/${item.id}`, { method: 'PATCH', body: JSON.stringify({ purchased: !item.purchased }) }); await load() }}>{item.purchased && <Check size={13} />}</button><div className="meal-info"><b>{item.name}</b><small>{item.quantity} шт.</small></div><button className="row-more" onClick={async () => { await apiFetch(`/shopping-lists/${list.id}/items/${item.id}`, { method: 'DELETE' }); await load(); notify('Товар удалён') }}><X size={16} /></button></div>)}</div> : <div className="empty-state"><ShoppingBasket size={22} /><b>Список пуст</b><span>Добавьте первый товар.</span></div>}</section></> }

function Coach({ notify }: { notify: (s: string) => void }) { const [message, setMessage] = useState(''); const [messages, setMessages] = useState<Array<{ role: 'user' | 'assistant'; text: string }>>([]); const [loading, setLoading] = useState(false); const [provider, setProvider] = useState('local'); useEffect(() => { apiFetch('/ai/status').then(data => setProvider(data.provider || 'local')).catch(() => undefined) }, []); const ask = async (event: React.FormEvent) => { event.preventDefault(); const question = message.trim(); if (!question || loading) return; setMessage(''); setMessages(old => [...old, { role: 'user', text: question }]); setLoading(true); try { const data = await apiFetch('/ai/coach', { method: 'POST', body: JSON.stringify({ message: question }) }); setMessages(old => [...old, { role: 'assistant', text: data.message }]) } catch (e) { notify(e instanceof Error ? e.message : 'AI временно недоступен') } finally { setLoading(false) } }; return <><PageTitle eyebrow="FITLY AI" title="Ваш спокойный коуч" sub="AI анализирует только ваши записи и не ставит диагнозы." action={<button className="button secondary" onClick={() => setMessages([])}><BookOpen size={17} /> Очистить</button>} /><div className="coach-layout"><section className="card coach-chat"><div className="coach-header"><div className="coach-avatar"><Sparkles size={21} /></div><div><b>FITLY AI · {provider}</b><span>{provider === 'openai' ? 'OpenAI подключён; есть локальный fallback' : 'Бесплатный локальный режим'}</span></div><button className="dots" onClick={() => notify(`Провайдер: ${provider}`)}><MoreHorizontal size={19} /></button></div><div className="chat-messages">{messages.length ? messages.map((item, index) => <div className={item.role === 'user' ? 'chat-bubble user' : 'chat-bubble'} key={`${item.role}-${index}`}>{item.text}</div>) : <div className="empty-state"><Sparkles size={22} /><b>Спросите о своём дне</b><span>Например: «Как у меня с водой сегодня?»</span></div>}{loading && <div className="chat-bubble">Анализирую записи…</div>}</div><form className="chat-input" onSubmit={ask}><input value={message} onChange={e => setMessage(e.target.value)} placeholder="Ваш вопрос" /><button aria-label="Отправить" disabled={loading}><ArrowRight size={17} /></button></form><small className="ai-note"><CircleHelp size={13} /> Общие рекомендации, не медицинская консультация.</small></section><aside className="coach-side"><div className="card insight-card"><div className="insight-title"><span className="ai-orb small-orb"><Sparkles size={16} /></span><span>Статус провайдера</span></div><h3>{provider === 'openai' ? 'OpenAI active' : 'Local AI active'}</h3><p>Ответы строятся на реальных данных вашего дневника.</p></div></aside></div></> }

function Profile({ name, dark, setDark, notify, onLogout }: { name: string; dark: boolean; setDark: (v: boolean) => void; notify: (s: string) => void; onLogout: () => void }) { const [draft, setDraft] = useState(name); const saveProfile = async () => { try { await apiFetch('/profile', { method: 'PATCH', body: JSON.stringify({ name: draft }) }); notify('Профиль сохранён') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить') } }; const toggleTheme = async () => { const next = !dark; try { await apiFetch('/settings', { method: 'PATCH', body: JSON.stringify({ theme: next ? 'dark' : 'light' }) }); setDark(next); notify('Тема сохранена') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить тему') } }; const configureReminders = async () => { const waterReminder = window.confirm('Включить напоминания о воде?'); const mealReminder = window.confirm('Включить напоминания о приёмах пищи?'); try { await apiFetch('/settings', { method: 'PATCH', body: JSON.stringify({ notifications: { water: waterReminder, meal: mealReminder } }) }); notify('Напоминания сохранены') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось сохранить напоминания') } }; const openIntegrations = async () => { try { const data = await apiFetch('/integrations'); const count = (data.providers || []).filter((x: { status: string }) => x.status === 'connected').length; notify(count ? `${count} источник(а) подключено` : 'Подключённых устройств нет. Доступен ручной ввод.') } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось загрузить интеграции') } }; return <><PageTitle eyebrow="Профиль" title="Настройки под вас" sub="FITLY становится полезнее, когда знает ваш ритм." action={<button className="button secondary" onClick={saveProfile}><Check size={17} /> Сохранить</button>} /><div className="profile-layout"><section className="card profile-card"><div className="profile-cover"><div className="profile-avatar">{name.slice(0, 2).toUpperCase() || 'FT'}</div><button className="edit-avatar" onClick={() => notify('Аватар можно подключить через storage provider')}><Camera size={15} /></button></div><div className="profile-details"><h2>{name || 'Ваш профиль'}</h2><p className="muted">Данные сохраняются в защищённом аккаунте</p><div className="plan-pill"><Sparkles size={14} /> Free план</div></div><div className="profile-fields"><label>Имя<input value={draft} onChange={e => setDraft(e.target.value)} placeholder="Ваше имя" /></label><label>Цель<select defaultValue="Больше энергии"><option>Больше энергии</option><option>Сбалансированное питание</option><option>Больше активности</option></select></label><label>Единицы измерения<select defaultValue="Метрические"><option>Метрические</option><option>Имперские</option></select></label></div></section><BillingCard notify={notify} /><section className="card settings-card"><span className="section-kicker">Предпочтения</span><SettingRow icon={<Moon size={18} />} title="Тёмная тема" desc="Комфортный режим для вечера" control={<button className={dark ? 'switch on' : 'switch'} onClick={toggleTheme}><i /></button>} /><SettingRow icon={<Bell size={18} />} title="Напоминания" desc="Вода, приёмы пищи и привычки" control={<ChevronRight size={17} />} onClick={configureReminders} /><SettingRow icon={<HeartPulse size={18} />} title="Подключённые устройства" desc="Показать реальные статусы источников" control={<ChevronRight size={17} />} onClick={openIntegrations} /><SettingRow icon={<LogOut size={18} />} title="Выйти из аккаунта" desc="Завершить текущую сессию" control={<ChevronRight size={17} />} onClick={async () => { await apiFetch('/auth/logout', { method: 'POST' }).catch(() => undefined); onLogout() }} /></section></div></> }
function BillingCard({ notify }: { notify: (s: string) => void }) { const [plans, setPlans] = useState<Array<{ id: string; name: string; price: number; features: string[] }>>([]); useEffect(() => { apiFetch('/billing/plans').then(data => setPlans(data.plans || [])).catch(() => notify('Не удалось загрузить планы')) }, []); const checkout = async (plan: string) => { if (plan === 'free') return notify('Free план уже активен'); try { const data = await apiFetch('/billing/checkout', { method: 'POST', body: JSON.stringify({ plan }) }); if (data.url) window.location.href = data.url } catch (e) { notify(e instanceof Error ? e.message : 'Платежи пока не настроены') } }; return <section className="card settings-card billing-card"><span className="section-kicker">Подписка</span><h2>Выберите возможности FITLY</h2><div className="billing-plans">{plans.map(plan => <button className={plan.id === 'plus' ? 'billing-plan featured' : 'billing-plan'} key={plan.id} onClick={() => checkout(plan.id)}><b>{plan.name}</b><strong>{plan.price ? `${(plan.price / 100).toFixed(2)} €` : 'Бесплатно'}</strong><small>{plan.features[0]}</small></button>)}</div></section> }
function SettingRow({ icon, title, desc, control, onClick }: { icon: React.ReactNode; title: string; desc: string; control: React.ReactNode; onClick?: () => void }) { return <button className="setting-row" onClick={onClick}><span className="setting-icon">{icon}</span><span><b>{title}</b><small>{desc}</small></span>{control}</button> }
function PageTitle({ eyebrow, title, sub, action }: { eyebrow: string; title: string; sub: string; action?: React.ReactNode }) { return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="subheading">{sub}</p></div><div className="heading-actions">{action}</div></div> }

function AddFoodModal({ close, notify, onAdded }: { close: () => void; notify: (s: string) => void; onAdded: () => Promise<void> }) { const [query, setQuery] = useState(''); const [foods, setFoods] = useState<Array<{ id: string; name: string; kcal: number; protein: number; unit: string }>>([]); const [loading, setLoading] = useState(true); useEffect(() => { apiFetch(`/foods?q=${encodeURIComponent(query)}`).then(data => setFoods(data.items || [])).catch(() => notify('Не удалось загрузить базу продуктов')).finally(() => setLoading(false)) }, [query]); const createFood = async () => { const name = window.prompt('Название продукта'); if (!name?.trim()) return; const kcal = window.prompt('Калории на порцию', '0'); if (kcal === null) return; const protein = window.prompt('Белки, г', '0'); if (protein === null) return; const fat = window.prompt('Жиры, г', '0'); if (fat === null) return; const carbs = window.prompt('Углеводы, г', '0'); if (carbs === null) return; try { const result = await apiFetch('/foods', { method: 'POST', body: JSON.stringify({ name: name.trim(), kcal: Number(kcal), protein: Number(protein), fat: Number(fat), carbs: Number(carbs), unit: 'порция' }) }); await apiFetch('/meals', { method: 'POST', body: JSON.stringify({ foodId: result.item.id, type: 'snack', quantity: 1 }) }); await onAdded(); notify(`${name.trim()} добавлен в дневник`); close() } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось создать продукт') } }; return <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={e => e.target === e.currentTarget && close()}><motion.div className="modal" initial={{ opacity: 0, y: 20, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }}><div className="modal-head"><div><span className="section-kicker">Дневник питания</span><h2>Добавить продукт</h2></div><button className="close-button" onClick={close}><X size={19} /></button></div><div className="modal-search"><Search size={18} /><input autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="Найти продукт в базе" /></div><div className="modal-tabs"><button className="active">База FITLY</button></div><div className="food-options">{loading ? <div className="empty-state">Загрузка базы…</div> : foods.length ? foods.map(food => <button key={food.id} className="food-option" onClick={async () => { try { await apiFetch('/meals', { method: 'POST', body: JSON.stringify({ foodId: food.id, type: 'snack', quantity: 1 }) }); await onAdded(); notify(`${food.name} добавлен в дневник`); close() } catch (e) { notify(e instanceof Error ? e.message : 'Ошибка сохранения') } }}><div className="food-option-icon"><Apple size={17} /></div><span><b>{food.name}</b><small>{food.kcal} ккал · {food.protein} г белка · {food.unit}</small></span><Plus size={18} /></button>) : <div className="empty-state"><Search size={20} /><b>Продукт не найден</b><span>Создайте его ниже.</span></div>}</div><button className="custom-food" onClick={createFood}><Plus size={16} /> Создать свой продукт</button></motion.div></motion.div> }
function ScannerModal({ close, notify }: { close: () => void; notify: (s: string) => void }) { const [file, setFile] = useState<File | null>(null); const [preview, setPreview] = useState(''); const [result, setResult] = useState<{ name: string; ingredients?: string[]; portion?: string; calories?: number; protein?: number; fat?: number; carbs?: number; fiber?: number; confidence?: number } | null>(null); const [loading, setLoading] = useState(false); const select = (event: React.ChangeEvent<HTMLInputElement>) => { const next = event.target.files?.[0]; if (!next) return; setFile(next); setResult(null); const reader = new FileReader(); reader.onload = () => setPreview(String(reader.result || '')); reader.readAsDataURL(next) }; const analyze = async () => { if (!file || !preview) return; setLoading(true); try { const data = await apiFetch('/ai/food-scan', { method: 'POST', body: JSON.stringify({ image: preview }) }); setResult(data.result) } catch (e) { notify(e instanceof Error ? e.message : 'Не удалось распознать блюдо') } finally { setLoading(false) } }; return <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={e => e.target === e.currentTarget && close()}><motion.div className="modal scanner-modal" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}><div className="modal-head"><div><span className="section-kicker">FITLY AI</span><h2>Распознать блюдо</h2></div><button className="close-button" onClick={close}><X size={19} /></button></div>{result ? <div className="scan-result">{preview && <img className="scan-preview" src={preview} alt="Блюдо" />}<h3>{result.name}</h3><p className="muted">{result.portion || 'Порция определена приблизительно'} · уверенность {Math.round((result.confidence || 0) * 100)}%</p><div className="scan-nutrients"><span>{Math.round(result.calories || 0)} ккал</span><span>Б {Math.round(result.protein || 0)} г</span><span>Ж {Math.round(result.fat || 0)} г</span><span>У {Math.round(result.carbs || 0)} г</span></div><button className="button secondary full" onClick={() => { setResult(null); setFile(null); setPreview('') }}>Сканировать ещё</button></div> : <><label className="scanner-drop"><input type="file" accept="image/*" capture="environment" hidden onChange={select} />{preview ? <img className="scan-preview" src={preview} alt="Предпросмотр блюда" /> : <div className="scanner-frame"><ScanLine size={32} /></div>}<h3>{file ? file.name : 'Сфотографируйте блюдо'}</h3><p>Выберите фото или сделайте снимок. AI распознает блюдо и оценит нутриенты.</p><span className="button secondary">{file ? 'Выбрать другое фото' : 'Открыть камеру'}</span></label><button className="button primary full" disabled={!file || loading} onClick={analyze}>{loading ? 'Анализируем…' : 'Распознать блюдо'}</button><div className="ai-disclaimer"><CircleHelp size={15} /> Оценка приблизительная. Проверяйте результат перед добавлением.</div></>}</motion.div></motion.div> }

function AuthScreen({ onAuth }: { onAuth: (token: string) => void }) {
  const [mode, setMode] = useState<'login' | 'register'>('register'); const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false)
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setError(''); setLoading(true); try { const data = await apiFetch(`/auth/${mode}`, { method: 'POST', body: JSON.stringify(mode === 'register' ? { name, email, password } : { email, password }) }); onAuth(data.token) } catch (e) { setError(e instanceof Error ? e.message : 'Не удалось выполнить запрос') } finally { setLoading(false) } }
  return <div className="auth-page"><div className="auth-visual"><div className="brand"><div className="brand-mark"><Leaf size={18} /></div><span>FITLY</span></div><div className="auth-copy"><span className="section-kicker">ПИТАЙСЯ ОСОЗНАННО</span><h1>Ритм, в котором<br /><em>хорошо вам.</em></h1><p>Персональное wellness-пространство для питания, движения и привычек.</p><div className="auth-stat"><div className="auth-stat-icon"><TrendingUp size={17} /></div><span><b>Ваши данные — в одном месте</b><small>Питание, вода, активность и привычки</small></span></div></div></div><div className="auth-panel"><div className="auth-box"><span className="section-kicker">{mode === 'register' ? 'ДОБРО ПОЖАЛОВАТЬ' : 'С РАДОСТЬЮ ВИДИМ ВАС'}</span><h2>{mode === 'register' ? 'Создайте свой ритм' : 'С возвращением'}</h2><p>{mode === 'register' ? 'Начните с небольших изменений уже сегодня.' : 'Войдите, чтобы продолжить свой путь.'}</p><div className="auth-switch"><button type="button" className={mode === 'register' ? 'active' : ''} onClick={() => setMode('register')}>Регистрация</button><button type="button" className={mode === 'login' ? 'active' : ''} onClick={() => setMode('login')}>Вход</button></div><form onSubmit={submit}>{mode === 'register' && <label>Имя<input value={name} onChange={e => setName(e.target.value)} placeholder="Как к вам обращаться" required /></label>}<label>Email<input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@example.com" required /></label><label>Пароль<input type="password" minLength={8} value={password} onChange={e => setPassword(e.target.value)} placeholder="Минимум 8 символов" required /></label>{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={loading}>{loading ? 'Проверяем…' : mode === 'register' ? 'Создать аккаунт' : 'Войти в FITLY'} <ArrowRight size={16} /></button></form><small className="auth-legal">Продолжая, вы соглашаетесь с условиями использования и политикой конфиденциальности.</small></div></div></div>
}

export default App

createRoot(document.getElementById('root')!).render(<App />)
